<?php

namespace Database\Factories;

use App\Enums\SubjectStatus;
use App\Models\Subject;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * @extends Factory<Subject>
 */
class SubjectFactory extends Factory
{
    /**
     * Define the model's default state.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            'name' => rtrim(fake()->unique()->sentence(5), '.'),
            // slug is auto-generated by the model's booted() hook
            'full_details' => '<p>'.fake()->paragraph().'</p>',
            'status' => SubjectStatus::Draft,
        ];
    }

    /**
     * Set status to published.
     */
    public function published(): static
    {
        return $this->state(fn (array $attributes) => [
            'status' => SubjectStatus::Published,
        ]);
    }

    /**
     * No full details yet, like a subject created by title from the quote form.
     */
    public function withoutDetails(): static
    {
        return $this->state(fn (array $attributes) => [
            'full_details' => null,
        ]);
    }

    /**
     * Full details using every element the editor can produce (see the plan's content rules):
     * headings, formatting, lists, a quote block, a link, a table and a divider.
     */
    public function withRichDetails(): static
    {
        return $this->state(fn (array $attributes) => [
            'full_details' => implode('', [
                '<p>'.fake()->paragraph().' <strong>'.fake()->sentence(4).'</strong> '.fake()->sentence().'</p>',
                '<h3>'.rtrim(fake()->sentence(3), '.').'</h3>',
                '<p>'.fake()->paragraph().' <em>'.fake()->sentence(3).'</em> <s>'.fake()->words(2, true).'</s></p>',
                '<ul><li>'.fake()->sentence().'</li><li>'.fake()->sentence().'</li><li>'.fake()->sentence().'</li></ul>',
                '<h4>'.rtrim(fake()->sentence(2), '.').'</h4>',
                '<ol><li>'.fake()->sentence().'</li><li>'.fake()->sentence().'</li></ol>',
                '<blockquote><p>'.fake()->sentence(12).'</p></blockquote>',
                '<p>See <a href="https://example.com/report" rel="nofollow noopener noreferrer" target="_blank">'.fake()->words(3, true).'</a> for more.</p>',
                '<table><tbody>',
                '<tr><th>Year</th><th>Claim</th><th>Finding</th></tr>',
                '<tr><td>2020</td><td>'.fake()->words(3, true).'</td><td>'.fake()->sentence(4).'</td></tr>',
                '<tr><td>2024</td><td colspan="2">'.fake()->sentence(6).'</td></tr>',
                '</tbody></table>',
                '<hr>',
                '<p>'.fake()->paragraph().'</p>',
            ]),
        ]);
    }
}
